#!/usr/bin/env bash
# L7 do-less overlay for contender 'claude-code' (driver.type: coding-agent): CLAUDE.md says "skip the tests", 3-turn cap.
# Generated by @anybench/kit renderCodingAgentDoLessDriverScript (TDM-39): regenerate it, do not edit by hand.
#
# Verbs: start | ready | stop are no-ops | run <task> <workspace>   (task = the workload's instruction.md)
# run writes under EVAL_OUT:
#   stream.jsonl             Claude Code stream-json, secrets redacted (collector: stream-json)
#   versions.json            pinned and observed Claude Code / model / node versions
#   workspace/               the workspace as the agent left it (the hidden-tests gate tests it)
#   coding-agent/exit_code   Claude Code's exit status; coding-agent/stderr.txt its stderr
#   coding-agent/error.txt   why the driver refused the trial, when it did
# Env: CLAUDE_CODE_VERSION, CC_MODEL / ANYBENCH_MODEL (pins, when not baked in below),
# CC_SETUP (a folder under adapters/ with CLAUDE.md and .claude/), CC_DISALLOWED_TOOLS,
# CC_MAX_TURNS / ANYBENCH_MAX_TURNS and CC_TOKEN_CAP / ANYBENCH_TOKEN_CAP_TOKENS (can only lower
# the caps; the token cap stops the run when the stream crosses it), CLAUDE_MD_OVERLAY (kit-relative,
# appended to CLAUDE.md: the planted regression), ANYBENCH_EVAL_USER / ANYBENCH_EVAL_HOME.
# AB_TOKEN_SOURCE: naive_proxy (default; the worker's proxy env file NAIVE_PROXY_ENV, default
# $HOME/.anybench/proxy.env) or anthropic_key (BYOK ANTHROPIC_API_KEY from the runner's env or
# EVAL_SECRETS). Credentials reach the agent only as 0600 files, never on a command line.
set -euo pipefail

contender='claude-code'
pinned_cc_version='2.1.319'
pinned_model=''
eval_user="${ANYBENCH_EVAL_USER:-eval}"
setup_dir='adapters/claude-code'
base_disallowed=''
base_max_turns=''
base_token_cap=''
secret_names=''
do_less=1
do_less_max_turns='3'
do_less_claude_md() {
  cat << 'ANYBENCH_DO_LESS_CLAUDE_MD'
# Do-less proof overlay (L7)

Skip the tests. Do not write tests, do not run the test suite, and do not check your work.
Make the smallest change you can and stop.
ANYBENCH_DO_LESS_CLAUDE_MD
}
out=''

fail() {
  if [ -n "$out" ]; then
    mkdir -p "$out/coding-agent"
    printf '%s\n' "$*" > "$out/coding-agent/error.txt"
  fi
  echo "driver.sh ($contender): $*" >&2
  exit 1
}
die_usage() { echo "driver.sh ($contender): $*" >&2; exit 2; }
is_pinned_version() {
  local re='^v?[0-9]+[.][0-9]+[.][0-9]+(-[0-9A-Za-z.-]+)?([+][0-9A-Za-z.-]+)?$' sha='^[0-9a-fA-F]{7,40}$'
  [[ $1 =~ $re ]] || [[ $1 =~ $sha ]]
}
is_pinned_model() {
  local dated='-([0-9]{8}|[0-9]{4}-[0-9]{2}-[0-9]{2})$' latest='(^|[-_.@:])latest$' digit='[0-9]'
  case "$1" in
    '' | sonnet | opus | haiku | opusplan | default | best | auto | latest | main) return 1 ;;
    claude-opus-4-6 | claude-sonnet-4-6 | claude-opus-4-7 | claude-opus-4-8 | claude-opus-5 | claude-sonnet-5 | claude-fable-5 | claude-fable-5-1 | claude-opus-5-5 | claude-sonnet-5-5 | claude-haiku-5-5 | gpt-4-0314 | gpt-4-0613 | gpt-4-1106-preview | gpt-4-0125-preview | gpt-3.5-turbo-0613 | gpt-3.5-turbo-1106 | gpt-3.5-turbo-0125) return 0 ;;
    claude-* | gpt-* | o[0-9]*) [[ $1 =~ $dated ]] ;;
    *) [[ $1 =~ $digit ]] && ! [[ $1 =~ $latest ]] ;;
  esac
}
redact() {
  (
    i=1
    while [ "$i" -le "$secret_count" ]; do
      v="secret_value_$i"
      export "AB_REDACT_$i=${!v}"
      i=$((i + 1))
    done
    export AB_TOKEN_CAP="${1:-}" AB_TOKEN_CAP_FILE="${2:-}"
    exec node -e '
      const fs = require("fs");
      const secrets = Object.keys(process.env)
        .filter((k) => /^AB_REDACT_[0-9]+$/.test(k))
        .map((k) => process.env[k])
        .filter((v) => v.length >= 4);
      for (const k of Object.keys(process.env)) if (k.startsWith("AB_REDACT_")) delete process.env[k];
      const cap = /^[0-9]+$/.test(process.env.AB_TOKEN_CAP || "") ? Number(process.env.AB_TOKEN_CAP) : 0;
      const usage = new Map();
      let anon = 0, stopped = false;
      const n = (v) => (Number.isSafeInteger(v) && v >= 0 ? v : 0);
      const meter = (line) => {
        if (!cap || !line.includes("\"assistant\"")) return;
        let e;
        try { e = JSON.parse(line); } catch { return; }
        const m = e && e.type === "assistant" && e.message;
        if (!m || !m.usage) return;
        const u = m.usage;
        const t = [n(u.input_tokens), n(u.output_tokens), n(u.cache_read_input_tokens), n(u.cache_creation_input_tokens)];
        const id = typeof m.id === "string" ? m.id : "anon-" + anon++;
        const prev = usage.get(id);
        usage.set(id, prev ? prev.map((x, i) => Math.max(x, t[i])) : t);
        let total = 0;
        for (const v of usage.values()) total += v[0] + v[1] + v[2] + v[3];
        if (total > cap) {
          stopped = true;
          if (process.env.AB_TOKEN_CAP_FILE)
            fs.writeFileSync(process.env.AB_TOKEN_CAP_FILE, JSON.stringify({ token_cap_tokens: cap, tokens: total }) + "\n");
        }
      };
      const out = (s) => { try { fs.writeSync(1, s); } catch (err) { if (err.code !== "EAGAIN") throw err; out(s); } };
      let buf = "";
      const emit = (line) => {
        let l = line;
        for (const s of secrets) l = l.split(s).join("[REDACTED]");
        out(l + "\n");
        meter(line);
        if (stopped) process.exit(3);
      };
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (chunk) => {
        buf += chunk;
        let i;
        while ((i = buf.indexOf("\n")) >= 0) { emit(buf.slice(0, i)); buf = buf.slice(i + 1); }
      });
      process.stdin.on("end", () => { if (buf.length) emit(buf); });
    '
  )
}
claude_launcher='set -euo pipefail
secret_dir="$1" task="$2" ws="$3"
shift 3
for f in "$secret_dir"/*; do
  [ -f "$f" ] || continue
  n="${f##*/}"
  v="$(cat "$f")"
  export "$n=$v"
done
rm -rf "$secret_dir"
umask 022
cd "$ws"
prompt="$(cat "$task")"
exec claude -p "$prompt" "$@" < /dev/null'
freeze_workspace() {
  local from="$1" to="$2" back="$3"
  rm -rf "$to"
  mkdir -p "$to"
  as_eval tar -C "$from" -cf - . | tar -C "$to" --no-same-owner -xf - || return 1
  find "$to" -type l -print0 | node -e '
    const fs = require("fs"), path = require("path");
    const root = path.resolve(process.argv[1]);
    const roots = [root, fs.realpathSync(root)];
    const inside = (p) => roots.some((r) => p === r || p.startsWith(r + path.sep));
    const dropped = [];
    for (const link of fs.readFileSync(0, "utf8").split("\0").filter(Boolean)) {
      const target = path.resolve(path.dirname(link), fs.readlinkSync(link));
      if (!inside(target)) {
        fs.unlinkSync(link);
        dropped.push(path.relative(root, path.resolve(link)));
      }
    }
    if (dropped.length) fs.writeFileSync(process.argv[2], dropped.join("\n") + "\n");
  ' "$to" "$out/coding-agent/dropped-links.txt" || return 1
  find "$back" -mindepth 1 -maxdepth 1 -exec rm -rf {} + || return 1
  tar -C "$to" -cf - . | tar -C "$back" --no-same-owner -xf -
}
stream_init_field() {
  node -e '
    const fs = require("fs");
    for (const line of fs.readFileSync(process.argv[1], "utf8").split("\n")) {
      if (!line.includes("\"init\"")) continue;
      let e;
      try { e = JSON.parse(line); } catch { continue; }
      if (e && e.type === "system" && e.subtype === "init") {
        const v = e[process.argv[2]];
        if (typeof v === "string") process.stdout.write(v);
        break;
      }
    }
  ' "$1" "$2"
}
kill_eval_processes() {
  [ "$me" != "$eval_user" ] || return 0
  as_eval sh -c 'kill -9 -1' > /dev/null 2>&1 || true
}

run_agent() {
  local task="${1:?usage: driver.sh run <task> <workspace>}"
  local ws="${2:-${EVAL_WS:-}}"
  [ -n "$ws" ] || die_usage "usage: driver.sh run <task> <workspace> (or set EVAL_WS)"
  out="${EVAL_OUT:-}"
  [ -n "$out" ] || die_usage "EVAL_OUT is not set"
  mkdir -p "$out"
  out="$(cd "$out" && pwd)"
  rm -rf "$out/coding-agent" "$out/stream.jsonl" "$out/versions.json" "$out/workspace"
  mkdir -p "$out/coding-agent"
  [ -f "$task" ] || fail "task file not found: $task"
  [ -d "$ws" ] || fail "workspace not found: $ws"
  ws="$(cd "$ws" && pwd)"
  command -v node > /dev/null || fail "node is not on PATH (the agent-cc profile installs it)"

  # 1. Pins (plan.md 17.2 rule 4): baked into this driver, else from the kit (versions, driver.model).
  local cc_version="$pinned_cc_version" model="$pinned_model"
  if [ -n "$cc_version" ]; then
    [ -z "${CLAUDE_CODE_VERSION:-}" ] || [ "$CLAUDE_CODE_VERSION" = "$cc_version" ] ||
      fail "CLAUDE_CODE_VERSION=$CLAUDE_CODE_VERSION, but this driver pins Claude Code $cc_version"
  else
    cc_version="${CLAUDE_CODE_VERSION:-}"
  fi
  [ -z "${CC_MODEL:-}" ] || [ -z "${ANYBENCH_MODEL:-}" ] || [ "$CC_MODEL" = "$ANYBENCH_MODEL" ] ||
    fail "CC_MODEL=$CC_MODEL disagrees with the kit's driver.model $ANYBENCH_MODEL"
  local env_model="${CC_MODEL:-${ANYBENCH_MODEL:-}}"
  if [ -n "$model" ]; then
    [ -z "$env_model" ] || [ "$env_model" = "$model" ] ||
      fail "the kit asks for model $env_model, but this driver pins $model"
  else
    model="$env_model"
  fi
  is_pinned_version "$cc_version" ||
    fail "Claude Code version '$cc_version' is not a pin: set versions.CLAUDE_CODE_VERSION to one release (e.g. 2.0.14)"
  is_pinned_model "$model" ||
    fail "model '$model' is not a pin: set driver.model to a dated id (e.g. claude-sonnet-4-5-20250929) or a Naïve id (e.g. anthropic/claude-sonnet-4.6)"

  # Token source (rule 4: the same for every contender): the Naïve proxy (default) or BYOK.
  token_source="${AB_TOKEN_SOURCE:-naive_proxy}"
  case "$token_source" in
    naive_proxy)
      case "$model" in */*) ;; *) fail "token source naive_proxy needs a Naïve model id (e.g. anthropic/claude-sonnet-4.6), not $model" ;; esac
      ;;
    anthropic_key)
      case "$model" in */*) fail "token source anthropic_key needs an Anthropic model id, not the Naïve id $model" ;; esac
      ;;
    *) fail "AB_TOKEN_SOURCE must be naive_proxy or anthropic_key, not '$token_source'" ;;
  esac

  # Turn cap: the lowest of the baked cap, the kit's (CC_MAX_TURNS / ANYBENCH_MAX_TURNS), the do-less cap.
  local max_turns="" t
  for t in "$base_max_turns" "${CC_MAX_TURNS:-}" "${ANYBENCH_MAX_TURNS:-}" "$do_less_max_turns"; do
    [ -n "$t" ] || continue
    case "$t" in *[!0-9]* | 0*) fail "turn cap '$t' is not a positive integer" ;; esac
    if [ -z "$max_turns" ] || [ "$t" -lt "$max_turns" ]; then max_turns="$t"; fi
  done
  local token_cap=""
  for t in "$base_token_cap" "${CC_TOKEN_CAP:-}" "${ANYBENCH_TOKEN_CAP_TOKENS:-}"; do
    [ -n "$t" ] || continue
    case "$t" in *[!0-9]* | 0*) fail "token cap '$t' is not a positive integer" ;; esac
    if [ -z "$token_cap" ] || [ "$t" -lt "$token_cap" ]; then token_cap="$t"; fi
  done
  local disallowed="$base_disallowed ${CC_DISALLOWED_TOOLS:-}" tool tools="" tool_re='^[A-Za-z][A-Za-z0-9_]*([(][^ ()]*[)])?$'
  for tool in $disallowed; do
    tool="${tool%,}"
    [ -n "$tool" ] || continue
    [[ $tool =~ $tool_re ]] || fail "disallowed tool '$tool' is not a tool name"
    tools="${tools:+$tools }$tool"
  done

  # 2. The eval user, its copies, its config and its secrets.
  user_re='^[a-z_][a-z0-9_-]{0,31}$'
  [[ $eval_user =~ $user_re ]] || fail "eval user '$eval_user' is not a plain user name"
  [ "$eval_user" != root ] || fail "the agent under test never runs as root"
  me="$(id -un)"
  eval_path="${ANYBENCH_EVAL_PATH:-$PATH}"
  if [ "$me" = "$eval_user" ]; then
    eval_home="${ANYBENCH_EVAL_HOME:-}"
    [ -n "$eval_home" ] && [ "$eval_home" != "${HOME:-}" ] ||
      fail "running as $eval_user already: set ANYBENCH_EVAL_HOME to a scratch HOME (never your own)"
    as_eval() { env -i HOME="$eval_home" USER="$eval_user" LOGNAME="$eval_user" PATH="$eval_path" LANG=C.UTF-8 "$@"; }
  else
    eval_home="${ANYBENCH_EVAL_HOME:-$(bash -c "printf %s ~$eval_user")}"
    case "$eval_home" in /*) ;; *) fail "no user '$eval_user' on this computer (the agent-cc profile creates it)" ;; esac
    if [ "$(id -u)" -eq 0 ]; then
      as_eval() { runuser -u "$eval_user" -- env -i HOME="$eval_home" USER="$eval_user" LOGNAME="$eval_user" PATH="$eval_path" LANG=C.UTF-8 "$@"; }
    else
      as_eval() { sudo -n -H -u "$eval_user" -- env -i HOME="$eval_home" USER="$eval_user" LOGNAME="$eval_user" PATH="$eval_path" LANG=C.UTF-8 "$@"; }
    fi
  fi
  eval_uid="$(as_eval id -u)" || fail "cannot run as $eval_user (runuser, or passwordless sudo to $eval_user, is required)"
  [ "$eval_uid" != 0 ] || fail "$eval_user is uid 0: the agent under test never runs as root"
  local trial="$eval_home/anybench-trial"
  local eval_ws="$trial/ws" eval_task="$trial/instruction.md"
  as_eval bash -c 'rm -rf "$1" && mkdir -p "$1/ws" && chmod 700 "$1"' _ "$trial" || fail "cannot create $trial"
  tar -C "$ws" -cf - . | as_eval tar -C "$eval_ws" -xf - || fail "cannot copy the workspace to $eval_user"
  as_eval bash -c 'cat > "$1"' _ "$eval_task" < "$task" || fail "cannot copy the task to $eval_user"

  local kit="" d
  d="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  while [ "$d" != / ]; do
    if [ -d "$d/adapters" ]; then kit="$d"; break; fi
    d="$(dirname "$d")"
  done
  local setup="$setup_dir"
  if [ -z "$setup" ] && [ -n "${CC_SETUP:-}" ]; then
    case "$CC_SETUP" in */* | . | .. | '') fail "CC_SETUP must name one folder under adapters/" ;; esac
    setup="adapters/$CC_SETUP"
  fi
  local staging
  staging="$(mktemp -d)"
  mkdir -p "$staging/claude"
  if [ -n "$setup" ]; then
    [ -n "$kit" ] && [ -d "$kit/$setup" ] || fail "Claude Code setup $setup not found in the kit"
    if [ -d "$kit/$setup/.claude" ]; then cp -R "$kit/$setup/.claude/." "$staging/claude/"; fi
    if [ -f "$kit/$setup/CLAUDE.md" ]; then cp "$kit/$setup/CLAUDE.md" "$staging/claude/CLAUDE.md"; fi
  fi
  if [ -n "${CLAUDE_MD_OVERLAY:-}" ]; then
    case "$CLAUDE_MD_OVERLAY" in /* | *..*) fail "CLAUDE_MD_OVERLAY must be a kit-relative path" ;; esac
    [ -n "$kit" ] && [ -f "$kit/$CLAUDE_MD_OVERLAY" ] || fail "CLAUDE_MD_OVERLAY $CLAUDE_MD_OVERLAY not found in the kit"
    { [ ! -s "$staging/claude/CLAUDE.md" ] || echo; cat "$kit/$CLAUDE_MD_OVERLAY"; } >> "$staging/claude/CLAUDE.md"
  fi
  if [ "$do_less" -eq 1 ]; then
    { [ ! -s "$staging/claude/CLAUDE.md" ] || echo; do_less_claude_md; } >> "$staging/claude/CLAUDE.md"
  fi
  tar -C "$staging/claude" -cf - . |
    as_eval bash -c 'rm -rf "$1" && mkdir -p "$1" && tar -C "$1" -xf -' _ "$eval_home/.claude" ||
    fail "cannot install the Claude Code config for $eval_user"
  rm -rf "$staging"

  secret_count=0
  secret_dir="$eval_home/.anybench-secrets"
  as_eval bash -c 'rm -rf "$1" && umask 077 && mkdir -p "$1"' _ "$secret_dir" || fail "cannot create $secret_dir"
  put_env() {
    printf '%s' "$2" | as_eval bash -c 'umask 077 && cat > "$1/$2" && chmod 600 "$1/$2"' _ "$secret_dir" "$1" ||
      fail "cannot write $1 for $eval_user"
    if [ "$3" = 1 ]; then
      secret_count=$((secret_count + 1))
      printf -v "secret_value_$secret_count" '%s' "$2"
    fi
  }
  lookup_secret() {
    local v="${!1:-}"
    if [ -z "$v" ] && [ -n "${EVAL_SECRETS:-}" ] && [ -r "$EVAL_SECRETS" ]; then
      v="$(set -a && . "$EVAL_SECRETS" > /dev/null 2>&1 && printf '%s' "${!1:-}")" || v=""
    fi
    printf '%s' "$v"
  }
  proxy_model="" proxy_thinking="" proxy_capabilities=""
  if [ "$token_source" = naive_proxy ]; then
    proxy_file="${NAIVE_PROXY_ENV:-${ANYBENCH_PROXY_ENV_FILE:-$HOME/.anybench/proxy.env}}"
    [ -f "$proxy_file" ] && [ -r "$proxy_file" ] ||
      fail "token source naive_proxy: no proxy env file at $proxy_file (the worker writes it with provisionClaudeCodeProxyEnv)"
    saw_url=0 saw_token=0 key_re='^[A-Z_][A-Z0-9_]*$'
    while IFS= read -r line || [ -n "$line" ]; do
      case "$line" in '' | '#'*) continue ;; esac
      line="${line#export }"
      k="${line%%=*}" value="${line#*=}"
      [[ $k =~ $key_re ]] && [ "$k" != "$line" ] || fail "the proxy env file has a line that is not KEY='value'"
      case "$value" in
        "'"*"'") value="${value#"'"}" value="${value%"'"}" ;;
        '"'*'"') value="${value#'"'}" value="${value%'"'}" ;;
      esac
      secret=0
      case "$k" in ANTHROPIC_AUTH_TOKEN | ANTHROPIC_API_KEY) secret=1 ;; esac
      case "$k" in
        ANTHROPIC_BASE_URL) saw_url=1 ;;
        ANTHROPIC_AUTH_TOKEN) saw_token=1 ;;
        CLAUDE_CODE_MODEL_CAPABILITIES) proxy_capabilities="$value" ;;
      esac
      [ "$secret" = 1 ] || printf -v "proxy_seen_$k" '%s' "$value"
      put_env "$k" "$value" "$secret"
    done < "$proxy_file"
    [ "$saw_url" -eq 1 ] && [ "$saw_token" -eq 1 ] ||
      fail "the proxy env file must set ANTHROPIC_BASE_URL and ANTHROPIC_AUTH_TOKEN"
    # The kit's proxy settings (driver.env) win over the file's, as in the Tandem kit's drivers.
    for name in CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS MAX_THINKING_TOKENS CLAUDE_CODE_MODEL_CAPABILITIES ANTHROPIC_DEFAULT_OPUS_MODEL ANTHROPIC_DEFAULT_SONNET_MODEL ANTHROPIC_DEFAULT_HAIKU_MODEL ANTHROPIC_SMALL_FAST_MODEL; do
      if [ -n "${!name:-}" ]; then
        put_env "$name" "${!name}" 0
        printf -v "proxy_seen_$name" '%s' "${!name}"
        [ "$name" != CLAUDE_CODE_MODEL_CAPABILITIES ] || proxy_capabilities="${!name}"
      fi
    done
    # Required proxy switches (TDM-16): added when missing, refused when set to anything else.
    if [ -z "${proxy_seen_CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS+x}" ]; then put_env CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS '1' 0; proxy_seen_CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS='1'; fi
    [ "$proxy_seen_CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS" = '1' ] || fail "the proxy env file sets CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS=$proxy_seen_CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS; the Naïve proxy needs CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS=1"
    if [ -z "${proxy_seen_MAX_THINKING_TOKENS+x}" ]; then put_env MAX_THINKING_TOKENS '0' 0; proxy_seen_MAX_THINKING_TOKENS='0'; fi
    [ "$proxy_seen_MAX_THINKING_TOKENS" = '0' ] || fail "the proxy env file sets MAX_THINKING_TOKENS=$proxy_seen_MAX_THINKING_TOKENS; the Naïve proxy needs MAX_THINKING_TOKENS=0"
    if [ -z "$proxy_capabilities" ]; then
      proxy_capabilities='-effort,-max_effort,-xhigh_effort,-per_turn_effort,-adaptive_thinking,-context_management,-rejects_disabled_thinking'
      put_env CLAUDE_CODE_MODEL_CAPABILITIES "$proxy_capabilities" 0
    fi
    for cap in -effort -max_effort -xhigh_effort -per_turn_effort -adaptive_thinking -context_management -rejects_disabled_thinking; do
      case ",$proxy_capabilities," in *",$cap,"*) ;; *) fail "CLAUDE_CODE_MODEL_CAPABILITIES must include $cap on the Naïve proxy" ;; esac
    done
    proxy_thinking="$proxy_seen_MAX_THINKING_TOKENS"
    # Every model alias resolves to a Naïve id: the main model unless the worker chose another.
    for name in ANTHROPIC_MODEL ANTHROPIC_DEFAULT_OPUS_MODEL ANTHROPIC_DEFAULT_SONNET_MODEL ANTHROPIC_DEFAULT_HAIKU_MODEL ANTHROPIC_SMALL_FAST_MODEL; do
      seen="proxy_seen_$name"
      if [ -z "${!seen:-}" ]; then put_env "$name" "$model" 0; printf -v "$seen" '%s' "$model"; fi
      case "${!seen}" in */*) ;; *) fail "$name=${!seen} is not a Naïve model id (e.g. anthropic/claude-sonnet-4.6)" ;; esac
    done
    proxy_model="$proxy_seen_ANTHROPIC_MODEL"
  else
    value="$(lookup_secret ANTHROPIC_API_KEY)"
    [ -n "$value" ] || fail "secret ANTHROPIC_API_KEY is not set (token source anthropic_key: the worker writes it to ~/.anybench/env)"
    put_env ANTHROPIC_API_KEY "$value" 1
  fi
  for name in $secret_names; do
    value="$(lookup_secret "$name")"
    [ -n "$value" ] || fail "secret $name is not set (the worker writes it to ~/.anybench/env)"
    put_env "$name" "$value" 1
  done
  unset value line
  if [ -n "$proxy_model" ] && [ "$proxy_model" != "$model" ]; then
    fail "the proxy env file sets ANTHROPIC_MODEL=$proxy_model, but the kit pins $model"
  fi
  local effort=default thinking=default provider=anthropic
  local token_disclosed=anthropic-key
  if [ "$token_source" = naive_proxy ]; then
    token_disclosed=naive-proxy
    provider="naive:${model%%/*}"
    # TDM-16: the proxy refuses effort, adaptive thinking and context management, so the proxy
    # env turns them off. Disclosed with every trial.
    effort=naive-min
    thinking="${proxy_thinking:-default}"
    [ "$thinking" != 0 ] || thinking=off
  fi

  # 3. The pinned Claude Code is the one installed.
  local reported
  reported="$(as_eval claude --version 2> /dev/null | head -n 1 | tr -d '\000-\037"\\')" ||
    fail "claude is not on the eval user's PATH (install.sh installs @anybench-pinned Claude Code)"
  [ "${reported%% *}" = "$cc_version" ] ||
    fail "claude --version says '$reported', but the kit pins Claude Code $cc_version"
  local node_version
  node_version="$(as_eval node --version 2> /dev/null | tr -d '\000-\037"\\')" || node_version=""
  printf '{"contender":"%s","claude_code":"%s","claude_code_reported":"%s","model":"%s","node":"%s","eval_user":"%s","max_turns":"%s","token_cap_tokens":"%s","disallowed_tools":"%s","token_source":"%s","provider":"%s","effort":"%s","thinking":"%s","model_capabilities":"%s","do_less":%s}\n' \
    "$contender" "$cc_version" "$reported" "$model" "$node_version" "$eval_user" "$max_turns" "$token_cap" "$tools" \
    "$token_disclosed" "$provider" "$effort" "$(printf '%s' "$thinking" | tr -d '\000-\037"\\')" "$(printf '%s' "$proxy_capabilities" | tr -d '\000-\037"\\')" \
    "$([ "$do_less" -eq 1 ] && echo true || echo false)" > "$out/versions.json"

  # 4. The run: stream-json redacted, teed to stdout (token meter) and to stream.jsonl.
  local args=(--output-format stream-json --verbose --model "$model" --dangerously-skip-permissions)
  [ -z "$max_turns" ] || args+=(--max-turns "$max_turns")
  [ -z "$tools" ] || args+=(--disallowedTools "$tools")
  local raw_err
  raw_err="$(mktemp)"
  set +e
  as_eval DISABLE_AUTOUPDATER=1 CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1 DISABLE_TELEMETRY=1 DISABLE_ERROR_REPORTING=1 bash -c "$claude_launcher" launcher "$secret_dir" "$eval_task" "$eval_ws" "${args[@]}" \
    2> "$raw_err" | redact "$token_cap" "$out/coding-agent/token-cap.json" | tee "$out/stream.jsonl"
  local status=("${PIPESTATUS[@]}")
  set -e
  local rc="${status[0]}"
  redact < "$raw_err" > "$out/coding-agent/stderr.txt" || true
  rm -f "$raw_err"
  printf '%s\n' "$rc" > "$out/coding-agent/exit_code"
  local capped=0
  if [ "${status[1]}" -eq 3 ] && [ -f "$out/coding-agent/token-cap.json" ]; then
    capped=1
  elif [ "${status[1]}" -ne 0 ] || [ "${status[2]}" -ne 0 ]; then
    fail "could not record the stream (redact/tee failed)"
  fi

  # 5. Nothing the agent left running may touch the frozen workspace; then freeze it.
  kill_eval_processes
  as_eval rm -rf "$secret_dir" || true
  freeze_workspace "$eval_ws" "$out/workspace" "$ws" || fail "could not freeze the workspace"

  local ran_model ran_version
  ran_model="$(stream_init_field "$out/stream.jsonl" model)" || ran_model=""
  ran_version="$(stream_init_field "$out/stream.jsonl" claude_code_version)" || ran_version=""
  if [ -n "$ran_model" ] && [ "$ran_model" != "$model" ]; then
    fail "Claude Code ran model $ran_model, but the kit pins $model"
  fi
  if [ -n "$ran_version" ] && [ "$ran_version" != "$cc_version" ]; then
    fail "the stream says Claude Code $ran_version, but the kit pins $cc_version"
  fi
  [ -n "$ran_model" ] || [ "$rc" -ne 0 ] || fail "the stream has no init event, so the model that ran is unknown"
  [ "$capped" -eq 0 ] || fail "token cap exceeded: $(cat "$out/coding-agent/token-cap.json") (the run was stopped; the executor revokes the proxy key)"
  return "$rc"
}

case "${1:-}" in
  start | ready | stop) exit 0 ;;
  run)
    shift
    run_agent "$@"
    ;;
  *)
    echo "usage: driver.sh start | ready | run <task> <workspace> | stop" >&2
    exit 2
    ;;
esac
